# Gli allegati già caricati stanno in MEDIA_ROOT/registrations/ (pubblico).
# Li spostiamo, con lo stesso percorso relativo, in PRIVATE_MEDIA_ROOT: così i
# nomi salvati nel database ("registrations/xxx.pdf") restano validi.
SUBDIR = 'registrations'


def _move_tree(src_root, dst_root):
    src_dir = Path(src_root) / SUBDIR
    if not src_dir.is_dir():
        return 0, 0
    moved = skipped = 0
    for src in sorted(p for p in src_dir.rglob('*') if p.is_file()):
        dst = Path(dst_root) / src.relative_to(src_root)
        if dst.exists():
            skipped += 1  # già spostato in un'esecuzione precedente
            continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(src), str(dst))
        moved += 1
    # Rimuove le cartelle rimaste vuote.
    for d in sorted((p for p in src_dir.rglob('*') if p.is_dir()), reverse=True):
        if not any(d.iterdir()):
            d.rmdir()
    if not any(src_dir.iterdir()):
        src_dir.rmdir()
    return moved, skipped


def _is_test_database(schema_editor):
    name = str(schema_editor.connection.settings_dict.get('NAME', ''))
    return 'memory' in name or Path(name).name.startswith('test_')


def move_to_private(apps, schema_editor):
    if _is_test_database(schema_editor):
        return  # i test non devono toccare i file reali
    moved, skipped = _move_tree(settings.MEDIA_ROOT, settings.PRIVATE_MEDIA_ROOT)
    if moved or skipped:
        print(f'\n  Allegati iscrizioni resi privati: {moved} spostati, {skipped} già presenti.')


def move_back_to_media(apps, schema_editor):
    if _is_test_database(schema_editor):
        return
    _move_tree(settings.PRIVATE_MEDIA_ROOT, settings.MEDIA_ROOT)


